<script setup lang="ts">import { onMounted, ref } from 'vue';import { api } from '../api/client';import AsyncState from '../components/AsyncState.vue';const loading=ref(true),error=ref(''),health=ref<Record<string,unknown>>({});async function refresh(){loading.value=true;error.value='';try{health.value=await api('/health/ready')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}onMounted(refresh)</script>
<template><section class="view-head"><div><p class="eyebrow">S0 · S1 · S2 VALIDATION</p><h1>Operational overview</h1><p>Evidence-led diagnosis with simulator-only actions and an immutable real-site read boundary.</p></div><button @click="refresh">Refresh</button></section><AsyncState :loading="loading" :error="error"><section class="metric-grid"><article><small>Platform</small><strong>{{health.status}}</strong><span>Migration-aware readiness</span></article><article><small>Real endpoints</small><strong>READ ONLY</strong><span>Browse · Read · Subscribe</span></article><article><small>Actions</small><strong>SIMULATOR</strong><span>Approval and snapshot bound</span></article></section></AsyncState><section class="panel"><h2>Assurance boundary</h2><ol class="timeline"><li><b>Acquire</b><span>Allowlisted signals with quality and lineage</span></li><li><b>Diagnose</b><span>Residuals, evidence, hypotheses, safe checks</span></li><li><b>Approve</b><span>Maker-checker decision bound to plan and simulator digest</span></li><li><b>Evaluate</b><span>Frozen corpus, red lines, signed promotion record</span></li></ol></section></template>
